  if (!Array.isArray(arr)) {
    throw new TypeError('Input must be an array');
  }

  if (arr.length === 0) {
    return null;
  }

  // ---- accumulate sum while checking each element -----------------------
  let sum = 0;
  for (const v of arr) {
    if (typeof v !== 'number' || !Number.isFinite(v)) {
      throw new TypeError('All elements must be finite numbers');
    }
    sum += v;
  }

  // ---- overflow guard: reject non‑finite computed result ---------------
  if (!Number.isFinite(sum)) {
    throw new TypeError('Resulting sum is non‑finite (overflow)');
  }

  // ---- final average ----------------------------------------------------
  const avg = sum / arr.length;
  // The division cannot produce a non‑finite value if `sum` is finite,
  // but we keep the guard for completeness.
  if (!Number.isFinite(avg)) {
    throw new TypeError('Resulting average is non‑finite');
  }

  return avg;
}

/* =========================== tests =========================== */
