assert.strictEqual(average([5]), 5);
assert.strictEqual(average([]), null);
assert.strictEqual(average([-2, 2]), 0);
assert.strictEqual(average([0.1, 0.2, 0.3]), 0.2);

/* ---- Invalid inputs – must throw TypeError ---------------------- */
