assert.throws(() => average(null), TypeError);
assert.throws(() => average([1, undefined]), TypeError);
assert.throws(() => average([1, NaN]), TypeError);
assert.throws(() => average([1, Infinity]), TypeError);
assert.throws(() => average([1, '2']), TypeError);

/* ---- Overflow guard – non‑finite result must throw ------------- */
assert.throws(() => average([Number.MAX_VALUE, Number.MAX_VALUE]), TypeError);
